#!/usr/bin/env bash
# Steam wrapper for the 64-bit (steamrt64) client — generated by moon64 install.
#
# Derived from SLSsteam v2.9's path/steam wrapper, minus everything that is
# specific to the 32-bit scout client:
#   * no STEAM_FORCE_CLIENT=ubuntu12_32 pin and no -forcemanifestsuffix ubuntu12
#   * no library-inject.so (a 32-bit libcurl redirection shim; the 64-bit
#     client brings its own libcurl in the runtime, so it is not needed and
#     cannot load anyway)
#   * no $SLSDIR/lib32 on LD_LIBRARY_PATH (that path only exists for the
#     32-bit libcrypto workaround)
# Kept: the audit-stack guard, CloudRedirect via LD_PRELOAD, Lumen sidecar
# launch, netsock64 cert patch, and intact user Proton/Wine environment
# variables (WINEDLLOVERRIDES, PROTON_*). The desktop entry is not reconciled
# here: `moon64 on`/`off` own it.
set -uo pipefail

SLSDIR="$HOME/.local/share/SLSsteam"
MOON_DIR="${MOON64_DIR:-$HOME/.local/share/moon64}"
STATE_DIR="$MOON_DIR/state"
mkdir -p "$STATE_DIR" 2>/dev/null || true

log() { [ -n "${MOON64_VERBOSE:-}" ] && printf 'moon64: %s\n' "$*" >&2 || true; }

# Strip our own auditors inherited from a parent launch (desktop entries from
# older installs export them). Foreign auditors are preserved.
slsm_strip_own_auditors() {
    local old_ifs="$IFS" clean="" a
    IFS=:
    for a in ${LD_AUDIT:-}; do
        case "$a" in
            ''|*SLSsteam.so|*library-inject.so|*netsock64.so) continue ;;
            *) clean="${clean:+$clean:}$a" ;;
        esac
    done
    IFS="$old_ifs"
    printf '%s' "$clean"
}
SLSM_INHERITED_AUDIT="$(slsm_strip_own_auditors)"
if [ -n "$SLSM_INHERITED_AUDIT" ]; then export LD_AUDIT="$SLSM_INHERITED_AUDIT"; else unset LD_AUDIT; fi

# Resolve steam.sh in the Steam data root (never this wrapper itself) so
# steam.sh handles unset STEAM_RUNTIME, create_legacy_entry_points, and
# MAGIC_RESTART_EXITCODE=42 self-update restarts while keeping our LD_AUDIT stack.
SELF="$(readlink -f "$0" 2>/dev/null || echo "$0")"
STEAM_BIN=""
for r in "$HOME/.local/share/Steam" \
         "$HOME/.steam/steam" \
         "$HOME/.steam/debian-installation"; do
    if [ -x "$r/steam.sh" ] && [ -x "$r/steamrt64/steam" ] \
       && [ "$(readlink -f "$r/steam.sh" 2>/dev/null || echo "$r/steam.sh")" != "$SELF" ]; then
        STEAM_BIN="$r/steam.sh"
        break
    fi
done
if [ -z "$STEAM_BIN" ]; then
    for r in "$HOME/.local/share/Steam" \
             "$HOME/.steam/steam" \
             "$HOME/.steam/debian-installation"; do
        if [ -x "$r/steamrt64/steam" ] \
           && [ "$(readlink -f "$r/steamrt64/steam" 2>/dev/null || echo "$r/steamrt64/steam")" != "$SELF" ]; then
            STEAM_BIN="$r/steamrt64/steam"
            log "steam.sh missing; falling back to direct $STEAM_BIN"
            break
        fi
    done
fi
[ -n "$STEAM_BIN" ] || { echo "moon64: no steam.sh or steamrt64/steam binary found" >&2; exit 1; }
log "steam launcher: $STEAM_BIN"

# Steam must actually pick the 64-bit client; without these it re-execs to scout
# and none of the 64-bit libraries would load.
export STEAM_FORCE_CLIENT="steamrt64"
for r in "$HOME/.steam/steam" "$HOME/.local/share/Steam" "$HOME/.steam/debian-installation"; do
    [ -d "$r" ] || continue
    : > "$r/.steam-enable-steamrt64-client" 2>/dev/null || true
    rm -f "$r/.steam-disable-steamrt64-client" 2>/dev/null || true
done

# CloudRedirect cloud-save hook (LD_PRELOAD only: loading it as an auditor
# corrupts the client heap during init). Skipped silently when the installed
# hook is the 32-bit build — it cannot load into a 64-bit client.
CR_SO="$HOME/.local/share/CloudRedirect/cloud_redirect.so"
cr_info=""
[ -f "$CR_SO" ] && cr_info="$(file -b "$CR_SO" 2>/dev/null || true)"
case "$cr_info" in
    *'ELF 64-bit'*)
        export LD_PRELOAD="$CR_SO${LD_PRELOAD:+:$LD_PRELOAD}"
        ;;
    *)
        [ -f "$CR_SO" ] && log "CloudRedirect hook is not 64-bit; cloud saves disabled"
        ;;
esac

# Steam Input under Wayland (same rationale as upstream: no-op elsewhere).
if [ "${XDG_SESSION_TYPE:-}" = "wayland" ]; then
    for ext in /usr/lib/extest/libextest.so /usr/lib64/extest/libextest.so \
               /usr/lib/x86_64-linux-gnu/extest/libextest.so; do
        if [ -f "$ext" ]; then export LD_PRELOAD="${LD_PRELOAD:+$LD_PRELOAD:}$ext"; break; fi
    done
fi

# Lumen sidecar: detached, without the loader env (it must use its own libs).
LUMEN_DIR="$HOME/.local/share/Lumen"
if [ -x "$LUMEN_DIR/lumen" ] && ! pgrep -f "$LUMEN_DIR/lumen" >/dev/null 2>&1; then
    touch "$HOME/.steam/steam/.cef-enable-remote-debugging" 2>/dev/null || true
    touch "$HOME/.local/share/Steam/.cef-enable-remote-debugging" 2>/dev/null || true
    env -u LD_AUDIT -u LD_PRELOAD -u LD_LIBRARY_PATH \
        LUMEN_BACKEND_DIR="$LUMEN_DIR/luatools/backend" \
        LUMEN_LUA_DIR="$LUMEN_DIR/lua" \
        setsid "$LUMEN_DIR/lumen" >/dev/null 2>&1 < /dev/null &
fi

# Audit stack. Order matters: the cert patch first so it is installed before
# SLSsteam starts making networking calls, then SLSsteam itself.
AUDIT_LIST=""
add_audit() { [ -f "$1" ] && AUDIT_LIST="${AUDIT_LIST:+$AUDIT_LIST:}$1"; }
add_audit "$MOON_DIR/netsock64.so"
add_audit "$SLSDIR/SLSsteam.so"
if [ -z "$AUDIT_LIST" ]; then
    echo "moon64: neither netsock64.so nor SLSsteam.so found; refusing to start" >&2
    exit 1
fi
case ":$AUDIT_LIST:" in
    *netsock64*) log "netsock64 active" ;;
    *) log "netsock64 missing — P2P cert patch inactive" ;;
esac
if [ -n "$SLSM_INHERITED_AUDIT" ]; then
    export LD_AUDIT="$AUDIT_LIST:$SLSM_INHERITED_AUDIT"
else
    export LD_AUDIT="$AUDIT_LIST"
fi

# steam.sh also runs helper commands (mkdir, ln, readlink, ldd) before it
# execs the client, and they inherit this LD_AUDIT.  That is the same shape the
# 32-bit stack has always had and is safe: SLSsteam's setup() bails on any
# process whose name is not `steam`, and netsock64 only acts when a
# steamclient.so is actually opened.  Both helpers therefore no-op.
#
# Proton/Wine variables (WINEDLLOVERRIDES, PROTON_*) are intentionally untouched
# so user or per-game launch-option overrides reach Steam and Proton unchanged.
# (Only the detached Lumen sidecar above strips loader vars for itself.)
exec "$STEAM_BIN" "$@"
